//! Text formats for using the EQ outside the app.

use std::fmt::Write as _;

use crate::biquad::Filter;
use crate::eq_design::{EarEq, EqDesign};
use crate::freq_point;

/// Points in an exported graphic EQ (1/6 octave from 20 Hz to 20 kHz).
const GRAPHIC_EQ_POINTS: usize = 61;

/// Returns an Equalizer APO config applying a separate EQ to each ear.
#[must_use]
pub fn equalizer_apo(design: &EqDesign) -> String {
    let mut out = String::new();
    out.push_str(
        "# Generated by Earmark. Personal EQ from a hearing test; edits are overwritten.\n",
    );
    out.push_str("Channel: all\n");
    let _ = writeln!(out, "Preamp: {:.1} dB", design.preamp_db);
    for (channel, ear) in [("L", &design.left), ("R", &design.right)] {
        let _ = writeln!(out, "Channel: {channel}");
        write_filters(&mut out, &ear.filters);
    }
    out.push_str("Channel: all\n");
    out
}

/// Returns an AutoEQ-style `ParametricEQ.txt`, accepted by Equalizer APO, Peace,
/// Wavelet's parametric import, and many hardware EQ apps.
#[must_use]
pub fn parametric_eq(ear: &EarEq) -> String {
    let mut out = String::new();
    let preamp = -ear.peak_gain_db().max(0.0);
    let _ = writeln!(out, "Preamp: {:.1} dB", (preamp * 10.0).floor() / 10.0);
    write_filters(&mut out, &ear.filters);
    out
}

/// Returns an AutoEQ-style `GraphicEQ.txt` line, as used by Wavelet (Android).
///
/// Gains are shifted so none is positive, since the format has no preamp.
#[must_use]
pub fn graphic_eq(ear: &EarEq) -> String {
    let freqs = freq_point::log_spaced(20.0, 20_000.0, GRAPHIC_EQ_POINTS);
    let gains = ear.response_curve_db(&freqs);
    let peak = gains.iter().copied().fold(0.0, f32::max);
    let entries: Vec<String> = freqs
        .iter()
        .zip(&gains)
        .map(|(hz, gain)| format!("{} {:.1}", hz.round(), gain - peak))
        .collect();
    format!("GraphicEQ: {}\n", entries.join("; "))
}

fn write_filters(out: &mut String, filters: &[Filter]) {
    for (number, filter) in filters.iter().enumerate() {
        let _ = writeln!(
            out,
            "Filter {}: ON {} Fc {:.0} Hz Gain {:.1} dB Q {:.2}",
            number + 1,
            filter.kind.apo_code(),
            filter.hz,
            filter.gain_db,
            filter.q,
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::biquad::FilterKind;
    use crate::freq_point::FreqPoint;

    fn ear() -> EarEq {
        EarEq {
            target: vec![FreqPoint::new(1000.0, 4.0)],
            filters: vec![Filter {
                kind: FilterKind::Peak,
                hz: 1000.0,
                gain_db: 4.0,
                q: 1.41,
            }],
        }
    }

    #[test]
    fn apo_config_has_preamp_and_per_channel_filters() {
        let design = EqDesign::from_ears(ear(), EarEq::default(), -4.0);
        let config = equalizer_apo(&design);
        assert!(config.contains("Preamp: -4.0 dB\nChannel: L\nFilter 1: ON PK Fc 1000 Hz Gain 4.0 dB Q 1.41\nChannel: R\nChannel: all\n"));
    }

    #[test]
    fn parametric_eq_matches_autoeq_format() {
        assert_eq!(
            parametric_eq(&ear()),
            "Preamp: -4.0 dB\nFilter 1: ON PK Fc 1000 Hz Gain 4.0 dB Q 1.41\n"
        );
    }

    #[test]
    fn graphic_eq_is_never_positive() {
        let text = graphic_eq(&ear());
        assert!(text.starts_with("GraphicEQ: 20 "));
        let entries: Vec<&str> = text
            .trim_start_matches("GraphicEQ: ")
            .trim()
            .split("; ")
            .collect();
        assert_eq!(entries.len(), GRAPHIC_EQ_POINTS);
        for entry in entries {
            let gain: f32 = entry
                .split(' ')
                .nth(1)
                .expect("gain")
                .parse()
                .expect("number");
            assert!(gain <= 0.0, "{entry}");
        }
    }
}
